package dev.wowforever.importer.acquisition;
import static org.assertj.core.api.Assertions.*;
import com.sun.net.httpserver.HttpServer;
import dev.wowforever.importer.setup.*;
import java.net.*;import java.net.http.*;import java.nio.*;import java.nio.file.*;import java.security.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class RaidbotsHotfixMaterializerTest {
 @TempDir Path temporary;HttpServer server;AtomicInteger requests=new AtomicInteger();byte[] body;int status=200;
 @BeforeEach void start()throws Exception{body=snapshot(70450,1,2,3,4);server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/cache",exchange->{requests.incrementAndGet();exchange.sendResponseHeaders(status,body.length);try(var out=exchange.getResponseBody()){out.write(body);}});server.start();}
 @AfterEach void stop(){server.stop(0);}
 static byte[] snapshot(int build,int...statuses){ByteBuffer b=ByteBuffer.allocate(44+statuses.length*35).order(ByteOrder.LITTLE_ENDIAN);b.put(new byte[]{'X','F','T','H'}).putInt(9).putInt(build).put(new byte[32]);for(int s:statuses)b.put(new byte[]{'X','F','T','H'}).putInt(1).putInt(2).putInt(3).putInt(0x919be54e).putInt(647).putInt(3).put((byte)s).put(new byte[3]).put(new byte[]{1,2,3});return b.array();}
 RaidbotsHotfixMaterializer reader(long max,Duration timeout){return new RaidbotsHotfixMaterializer(URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/cache"),HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build(),max,100,timeout);}
 SetupPlan.JobContext job(String name)throws Exception{var p=new SetupPlan(Set.of(SetupPlan.Source.QUESTIE),Set.of(),Optional.empty(),List.of(),SetupPlan.currentPins(Set.of(SetupPlan.Source.QUESTIE)));return p.prepareJob(temporary.resolve("app"),Optional.empty(),name,List.of());}
 RaidbotsHotfixMaterializer.Pin pin(byte[] data)throws Exception{return new RaidbotsHotfixMaterializer.Pin("wow_classic_beta","1.60.1.70450","enUS",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data)));}
 RaidbotsHotfixMaterializer.Result run(SetupPlan.JobContext j)throws Exception{return reader(4096,Duration.ofSeconds(2)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,pin(body),()->false,p->{});}
 @Test void independentPermissionRequiredEvenWithValidPin()throws Exception{var j=job("denied");assertThatThrownBy(()->reader(4096,Duration.ofSeconds(2)).materialize(RaidbotsHotfixMaterializer.Permission.DENIED,j,pin(body),()->false,p->{})).hasMessageContaining("not selected");assertThat(requests).hasValue(0);assertThat(j.paths().cache().resolve("raidbots-hotfix")).doesNotExist();}
 @Test void publishesRawEvidenceAndRetainsEveryStatusWithoutMerging()throws Exception{var result=run(job("valid"));assertThat(result.structure().entries()).extracting(HotfixSnapshotReader.Entry::status).containsExactly(HotfixSnapshotReader.Status.values());assertThat(result.snapshot()).hasBinaryContent(body);assertThat(Files.readString(result.evidence())).contains("decodedRowsAvailable=false","cascRootVerified=false","status.REMOVED=1","status.INVALIDATED=1");}
 @Test void secondAcquisitionRechecksCacheWithZeroNetwork()throws Exception{var j=job("reuse");run(j);var result=run(j);assertThat(result.reused()).isTrue();assertThat(requests).hasValue(1);}
 @Test void alteredCacheEvidenceOrBytesCannotBeReused()throws Exception{var j=job("tamper");var result=run(j);Files.writeString(result.evidence(),"provider=BLIZZARD\n");assertThatThrownBy(()->run(j)).hasMessageContaining("evidence mismatch");assertThat(requests).hasValue(1);}
 @Test void corruptedCacheContentCannotBeReused()throws Exception{var j=job("bytes");var result=run(j);Files.write(result.snapshot(),snapshot(70451,1));assertThatThrownBy(()->run(j)).hasMessageContaining("content mismatch");}
 @Test void checksumMismatchLeavesNoCompleteInput()throws Exception{var j=job("hash");var expected=pin(body);body=snapshot(70450,1);assertThatThrownBy(()->reader(4096,Duration.ofSeconds(2)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,expected,()->false,p->{})).hasMessageContaining("SHA-256 mismatch");assertThat(j.paths().cache().resolve("raidbots-hotfix").resolve(expected.sha256())).doesNotExist();}
 @Test void wrongHeaderBuildIsRefusedEvenWithMatchingHash()throws Exception{body=snapshot(70451,1);assertThatThrownBy(()->run(job("build"))).hasMessageContaining("header build");}
 @Test void unsupportedProductLocaleAndBuildAreRejected(){assertThatIllegalArgumentException().isThrownBy(()->new RaidbotsHotfixMaterializer.Pin("wow","1.60.1.70450","enUS","a".repeat(64)));assertThatIllegalArgumentException().isThrownBy(()->new RaidbotsHotfixMaterializer.Pin("wow_classic_beta","1.15.9.70003","enUS","a".repeat(64)));assertThatIllegalArgumentException().isThrownBy(()->new RaidbotsHotfixMaterializer.Pin("wow_classic_beta","1.60.1.70450","deDE","a".repeat(64)));}
 @Test void unknownStatusAndTruncatedFramingAreRejected()throws Exception{body=snapshot(70450,5);assertThatThrownBy(()->run(job("status"))).hasMessageContaining("status");body=Arrays.copyOf(snapshot(70450,1),50);assertThatThrownBy(()->run(job("truncated"))).hasMessageContaining("Truncated");}
 @Test void requestSizeAndRedirectAreRefused()throws Exception{var j=job("limit");assertThatThrownBy(()->reader(44,Duration.ofSeconds(2)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,pin(body),()->false,p->{})).hasMessageContaining("byte limit");status=302;assertThatThrownBy(()->run(job("redirect"))).hasMessageContaining("HTTP 302");}
 @Test void cancellationBeforeOrDuringDownloadDoesNotPublish()throws Exception{var j=job("cancel");assertThatThrownBy(()->reader(4096,Duration.ofSeconds(2)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,pin(body),()->true,p->{})).isInstanceOf(CancellationException.class);assertThat(requests).hasValue(0);AtomicBoolean cancel=new AtomicBoolean();assertThatThrownBy(()->reader(4096,Duration.ofSeconds(2)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,pin(body),cancel::get,p->cancel.set(true))).isInstanceOf(CancellationException.class);assertThat(j.paths().cache().resolve("raidbots-hotfix").resolve(pin(body).sha256())).doesNotExist();}
 @Test void readerPreservesUnsignedIdsAndChecksVersionAndEntryBounds()throws Exception{Path p=temporary.resolve("snapshot");byte[] data=snapshot(70450,1);ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN).putInt(44+20,-1);Files.write(p,data);assertThat(new HotfixSnapshotReader().read(p,70450,4096,10,()->false).entries().getFirst().recordId()).isEqualTo(4294967295L);ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN).putInt(4,10);Files.write(p,data);assertThatThrownBy(()->new HotfixSnapshotReader().read(p,70450,4096,10,()->false)).hasMessageContaining("version");Files.write(p,snapshot(70450,1,2));assertThatThrownBy(()->new HotfixSnapshotReader().read(p,70450,4096,1,()->false)).hasMessageContaining("Too many");}
 @Test void stalledBodyTimesOutWithoutPublishingAndPreservesPreviousSnapshot()throws Exception{
  var j=job("timeout");var previous=run(j);byte[] previousBytes=Files.readAllBytes(previous.snapshot());
  server.removeContext("/cache");server.createContext("/cache",exchange->{exchange.sendResponseHeaders(200,1000);try{Thread.sleep(600);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}finally{exchange.close();}});
  var next=new RaidbotsHotfixMaterializer.Pin("wow_classic_beta","1.60.1.70450","enUS","b".repeat(64));
  assertThatThrownBy(()->reader(4096,Duration.ofMillis(150)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,next,()->false,p->{})).isInstanceOf(java.io.IOException.class);
  assertThat(previous.snapshot()).hasBinaryContent(previousBytes);assertThat(j.paths().cache().resolve("raidbots-hotfix").resolve(next.sha256())).doesNotExist();
 }

}
